def transform(g):
    g=[row[:] for row in g]
    H,W=len(g),len(g[0])
    from collections import Counter
    c=Counter(x for r in g for x in r)
    bg=c.most_common(1)[0][0]
    s=[k for k in c if k!=bg]
    s=s[0] if len(s)==1 else None
    pts=[(i,j) for i in range(H) for j in range(W) if g[i][j]==s]
    rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
    top,bot,l,r=min(rs),max(rs),min(cs),max(cs)
    rows_of_s={}
    for i,j in pts: rows_of_s.setdefault(i,0); rows_of_s[i]+=1
    for i in range(top,bot+1):
        if rows_of_s.get(i,0)>=2:
            for j in range(l,r+1):
                if g[i][j]!=s: g[i][j]=2
    for j in (l,r):
        for i in range(top,bot+1):
            if g[i][j]!=s: g[i][j]=2
    return g

